script="""import {pengajarHarness,plain} from './apps-script/absensi-dashboard/tests/support/pengajar-harness.mjs';const h=pengajarHarness(),t=h.t;const f={html:{},roles:{},tokens:{},responses:{},storageKey:h.teacher.storage_key};for(const n of ['Index','Beranda','Pengelolaan','Peserta','Profil','ManajemenAkses'])f.html[n]=t.c.keluaranAplikasiPanitia_(n,n).content;for(const [role,user] of Object.entries({teacher:h.teacher,admin:h.admin})){f.roles[role]=t.c.muatSesiAplikasiPanitia(user.token);f.tokens[role]=user.token;const call=(n,...a)=>h.call(user,n,...a);f.responses[role]={muatAwalIndex:call('muatAwalIndex'),muatBerandaIndex:call('muatBerandaIndex'),muatKehadiranIndex:call('muatKehadiranIndex','SES001'),muatDaftarIzinIndex:call('muatDaftarIzinIndex','SES001'),muatCatatanPerilakuIndex:call('muatCatatanPerilakuIndex','SES001'),muatRekapJPProgramIndex:call('muatRekapJPProgramIndex','PRG001'),muatNilaiPerilakuProgramIndex:call('muatNilaiPerilakuProgramIndex','PRG001'),muatPesertaProgramIndex:call('muatPesertaProgramIndex','PRG001','',0),muatProfilPesertaIndex:call('muatProfilPesertaIndex',{id_peserta:'PST001'}),muatEvaluasiPesertaSesi:call('muatEvaluasiPesertaSesi','SES001')};}for(const [n,a] of [['muatKelolaProgramIndex',['PRG001']],['muatManajemenAksesPanitia',[]],['muatMasterPesertaHapusIndex',[]],['muatKelolaPengajar',[]]])f.responses.admin[n]=h.call(h.admin,n,...a);f.roles.staff=t.c.muatSesiAplikasiPanitia(h.staff.token);f.tokens.staff=h.staff.token;f.responses.staff={...f.responses.teacher,muatAwalIndex:h.call(h.staff,'muatAwalIndex'),muatKehadiranIndex:h.call(h.staff,'muatKehadiranIndex','SES001')};f.flow=t.startApp();f.saved=h.call(h.teacher,'simpanEvaluasiPesertaSesi',h.payload());f.after={teacher:h.call(h.teacher,'muatEvaluasiPesertaSesi','SES001'),admin:h.call(h.admin,'muatEvaluasiPesertaSesi','SES001')};process.stdout.write(JSON.stringify(plain(f)));"""
